import{_ as t}from"./chunks/gnoblin-quickshell-firefox.D6kg-GkE.js";import{_ as a}from"./chunks/gnoblin-quickshell-files.BaLoUq4Q.js";import{_ as o,o as r,c as n,a2 as s}from"./chunks/framework.BfI5QxtK.js";const f=JSON.parse('{"title":"Wayland protocol catalog","description":"","frontmatter":{},"headers":[],"relativePath":"wayland-protocols.md","filePath":"wayland-protocols.md"}'),i={name:"wayland-protocols.md"};function l(d,e,c,g,p,h){return r(),n("div",null,[...e[0]||(e[0]=[s(`<h1 id="wayland-protocol-catalog" tabindex="-1">Wayland protocol catalog <a class="header-anchor" href="#wayland-protocol-catalog" aria-label="Permalink to &quot;Wayland protocol catalog&quot;">​</a></h1><p>This page covers the additional protocol globals Gnoblin registers or gates in a Gnoblin session. It does not list every core Wayland or upstream Mutter global. A client must bind the interface advertised by the running compositor; vendored XML alone does not mean a protocol is available.</p><h2 id="configure-availability" tabindex="-1">Configure availability <a class="header-anchor" href="#configure-availability" aria-label="Permalink to &quot;Configure availability&quot;">​</a></h2><p>Gnoblin enables the listed protocol gates by default in its own session. Some globals also use per-client filters, noted below. Disable a gate in <code>init.lua</code> with its Lua key:</p><div class="language-lua vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">lua</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">gnoblin.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">configure</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    protocols </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        wlr_screencopy </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Lua underscores become hyphens in the native setting name. Protocol globals are registered at compositor startup, so <strong>log out and back in</strong> after changing these gates. <code>gnoblinctl config reload</code> cannot add or remove an advertised global. GNOME&#39;s separate login session does not advertise Gnoblin-owned globals.</p><h2 id="available-interfaces" tabindex="-1">Available interfaces <a class="header-anchor" href="#available-interfaces" aria-label="Permalink to &quot;Available interfaces&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Lua key</th><th>Advertised interface</th><th>Use it for</th><th>Guide</th></tr></thead><tbody><tr><td><code>wlr_layer_shell</code></td><td><a href="https://github.com/kierandrewett/gnoblin/blob/main/src/protocols/layer-shell/wlr-layer-shell-unstable-v1.xml" target="_blank" rel="noreferrer"><code>zwlr_layer_shell_v1</code> (v5)</a></td><td>Bars, docks, launchers, overlays and exclusive zones</td><td><a href="./bring-your-own-shell">Choose a shell</a></td></tr><tr><td><code>wlr_screencopy</code></td><td><a href="https://github.com/kierandrewett/gnoblin/blob/main/src/protocols/screencopy/wlr-screencopy-unstable-v1.xml" target="_blank" rel="noreferrer"><code>zwlr_screencopy_manager_v1</code> (v3)</a></td><td>Native output capture</td><td><a href="/gnoblin/guides/permissions">Permissions</a></td></tr><tr><td><code>ext_foreign_toplevel_list</code></td><td><a href="https://github.com/kierandrewett/gnoblin/blob/main/src/protocols/foreign-toplevel-list/ext-foreign-toplevel-list-v1.xml" target="_blank" rel="noreferrer"><code>ext_foreign_toplevel_list_v1</code> (v1)</a></td><td>Enumerate toplevel windows</td><td><a href="./shell-integration">Shell integration</a></td></tr><tr><td><code>wlr_foreign_toplevel_management</code></td><td><a href="https://github.com/kierandrewett/gnoblin/blob/main/src/protocols/foreign-toplevel-management/wlr-foreign-toplevel-management-unstable-v1.xml" target="_blank" rel="noreferrer"><code>zwlr_foreign_toplevel_manager_v1</code> (v3)</a></td><td>Inspect and control windows</td><td><a href="./shell-integration">Shell integration</a></td></tr><tr><td><code>ext_data_control</code></td><td><a href="https://github.com/kierandrewett/gnoblin/blob/main/src/protocols/data-control/ext-data-control-v1.xml" target="_blank" rel="noreferrer"><code>ext_data_control_manager_v1</code> (v1)</a></td><td>Clipboard managers</td><td><a href="/gnoblin/guides/session_settings">Session settings</a></td></tr><tr><td><code>ext_idle_notify</code></td><td><a href="https://github.com/kierandrewett/gnoblin/blob/main/src/protocols/idle-notify/ext-idle-notify-v1.xml" target="_blank" rel="noreferrer"><code>ext_idle_notifier_v1</code> (v2)</a></td><td>Idle notifications</td><td><a href="/gnoblin/guides/session_settings">Session settings</a></td></tr><tr><td><code>wlr_gamma_control</code></td><td><a href="https://github.com/kierandrewett/gnoblin/blob/main/src/protocols/gamma-control/wlr-gamma-control-unstable-v1.xml" target="_blank" rel="noreferrer"><code>zwlr_gamma_control_manager_v1</code> (v1)</a></td><td>Per-output gamma</td><td><a href="/gnoblin/guides/session_settings">Session settings</a></td></tr><tr><td><code>wlr_output_power_management</code></td><td><a href="https://github.com/kierandrewett/gnoblin/blob/main/src/protocols/output-power-management/wlr-output-power-management-unstable-v1.xml" target="_blank" rel="noreferrer"><code>zwlr_output_power_manager_v1</code> (v1)</a></td><td>Output power state</td><td><a href="/gnoblin/guides/session_settings">Session settings</a></td></tr><tr><td><code>ext_background_effect_v1</code></td><td><a href="https://gitlab.freedesktop.org/wayland/wayland-protocols/-/blob/main/staging/ext-background-effect/ext-background-effect-v1.xml" target="_blank" rel="noreferrer"><code>ext_background_effect_manager_v1</code> (v1)</a></td><td>Client-defined background blur regions</td><td><a href="./background-effects">Background blur</a></td></tr><tr><td><code>xdg_decoration</code></td><td><a href="https://gitlab.freedesktop.org/wayland/wayland-protocols/-/blob/main/unstable/xdg-decoration/xdg-decoration-unstable-v1.xml" target="_blank" rel="noreferrer"><code>zxdg_decoration_manager_v1</code> (v1)</a></td><td>Negotiate client or server titlebars</td><td><a href="/gnoblin/guides/window_frames">Window frames</a></td></tr><tr><td><code>window_frame_renderer</code></td><td><a href="https://github.com/kierandrewett/gnoblin/blob/main/src/protocols/window-frame/gnoblin-window-frame-v1.xml" target="_blank" rel="noreferrer"><code>gnoblin_window_frame_manager_v1</code> (v1)</a></td><td>Manager is visible only to its registered renderer</td><td><a href="./frame-renderer-api">Frame renderer API</a></td></tr><tr><td><code>blur_fade</code></td><td><a href="https://github.com/kierandrewett/gnoblin/blob/main/src/protocols/blur-fade/gnoblin-blur-fade-v1.xml" target="_blank" rel="noreferrer"><code>gnoblin_blur_fade_manager_v1</code> (v1)</a></td><td>Per-item blur fade metadata</td><td><a href="./blur-fades">Blur fades</a></td></tr><tr><td><code>ext_session_lock</code></td><td><a href="https://github.com/kierandrewett/gnoblin/blob/main/src/protocols/session-lock/ext-session-lock-v1.xml" target="_blank" rel="noreferrer"><code>ext_session_lock_manager_v1</code> (v1)</a></td><td>Session locking for third-party lockers</td><td><a href="./session-lock">Session locking</a></td></tr></tbody></table><p>Each interface link opens its wire-level XML. The version is the maximum global version Gnoblin registers; bind no higher than the version advertised at runtime.</p><p>The frame-renderer manager is filtered to a renderer process launched by Gnoblin. Regular clients will not see it in <code>wayland-info</code>.</p><p>For standard protocol requests, events and enum values, see the <a href="https://wayland.freedesktop.org/docs/book/" target="_blank" rel="noreferrer">Wayland protocol documentation</a> and the <a href="https://gitlab.freedesktop.org/wayland/wayland-protocols" target="_blank" rel="noreferrer">wayland-protocols source</a>. This catalog identifies the interface to use and where to find its details.</p><p>For example, a layer-shell client controls its anchors, keyboard interactivity and exclusive zone. Gnoblin then places the surface and applies any matching <code>type = &quot;layer&quot;</code> <a href="/gnoblin/guides/window_rules">window rules</a>. A panel that animates its own whole surface can disable the compositor&#39;s layer animation for its namespace.</p><p><img src="`+t+'" alt="A Quickshell panel above Firefox in a Gnoblin session"></p><p><em>Quickshell positions the panel with layer shell.</em></p><p><img src="'+a+'" alt="GNOME Files open beneath a Quickshell panel in a Gnoblin session"></p><p><em>The same layer-shell surface sits above an ordinary application window.</em></p><p>Screen capture through <code>wlr_screencopy</code> is separate from capture through the desktop portal. The latter follows <a href="/gnoblin/guides/permissions">portal permission policy</a>. Turning off this global is not a blanket screen-sharing policy.</p><h2 id="interface-not-yet-available" tabindex="-1">Interface not yet available <a class="header-anchor" href="#interface-not-yet-available" aria-label="Permalink to &quot;Interface not yet available&quot;">​</a></h2><p><code>zwlr_output_manager_v1</code> has vendored XML but is not registered as a supported Gnoblin global. Mutter exposes its <code>org.gnome.Mutter.DisplayConfig</code> D-Bus API in the Gnoblin session; this is a Mutter interface, not a Gnoblin protocol. See the <a href="https://gnome.pages.gitlab.gnome.org/mutter/meta/class.MonitorManager.html" target="_blank" rel="noreferrer">Mutter monitor manager reference</a>.</p><p><a href="./gnoblinctl#workspaces-and-monitors"><code>gnoblinctl monitor list</code></a> reports monitor geometry but does not change display layouts. Session locking uses <code>ext_session_lock_manager_v1</code>; see <a href="./session-lock">Session locking</a> for its requirements and security behavior.</p><h2 id="inspect-a-running-session" tabindex="-1">Inspect a running session <a class="header-anchor" href="#inspect-a-running-session" aria-label="Permalink to &quot;Inspect a running session&quot;">​</a></h2><p>This catalog follows current Gnoblin source; older installed builds may advertise fewer globals.</p><p>Check <code>gnoblinctl version --json</code> and the running registry when packaging or debugging. Run <code>wayland-info</code> inside the Gnoblin session or devkit so it uses the right <code>WAYLAND_DISPLAY</code>. A checkout or XML file cannot prove which globals a login session advertised.</p>',23)])])}const _=o(i,[["render",l]]);export{f as __pageData,_ as default};
